            long x = n / cube(k);
            if (x == 0) {
                break;
            }
            ans += x;
        }
        return ans;
    }

    interface LongPredicate {
        boolean test(long value);
    }

    static long binSearch(LongPredicate f, long lo, long up, long eps) {
        up++;
        long cnt = up - lo;
        long mid;
        long step;

        while (cnt >= eps) {
            step = cnt / 2;
            mid = lo + step;
            if (!f.test(mid)) {
                lo = mid + eps;
                cnt -= step + eps;
            } else {
                cnt = step;
            }
        }
        return lo;
    }

