        private final byte[] buffer = new byte[1 << 16];
        private int position;
        private int length;

        Input(InputStream input) {
            this.input = input;
        }

        private int read() {
            if (position >= length) {
                try {
                    length = input.read(buffer);
                    position = 0;
                } catch (IOException e) {
                    return -1;
                }
                if (length <= 0) {
                    return -1;
                }
            }
            return buffer[position++];
