            int c;

            do {
                c = read();
            } while (c != -1 && Character.isWhitespace(c));

            if (c == -1) {
                return null;
            }

            while (c != -1 && !Character.isWhitespace(c)) {
                result.append((char) c);
                c = read();
            }

            return result.toString();
        }
