func cube(x int) int64 {
	return int64(x) * int64(x) * int64(x)
}

func foo(n int64) int64 {
	var ans int64
	for k := 2; ; k++ {
		x := n / cube(k)
		if x == 0 {
			break
		}
		ans += x
	}
	return ans
}

// najmniejszy argument, dla ktorego f(arg) zwraca prawde
// funkcja logiczna powinna byc niemalejaca
func bin_search(f func(int64) bool, lo, up, eps int64) int64 {
	up++
	cnt := up - lo
	var mid, step int64
	for cnt >= eps {
		step = cnt / 2
		mid = lo + step
		if !f(mid) {
			lo = mid + eps
			cnt -= step + eps
		} else {
			cnt = step
		}
	}
	return lo
}

func main() {
	m := getInt64()
	mx := int64(4949100894494448)
	x := func(n int64) bool {
		return foo(n) >= m
	}

	p := bin_search(x, 1, mx, 1)

	if foo(p) != m {
		p = -1
	}

	fmt.Println(p)
}

type Input struct {
	*bufio.Scanner
}

var globalInput = wrapStdin()

func wrapStdin() Input {
	sc := bufio.NewScanner(os.Stdin)
	sc.Split(bufio.ScanWords)
	return Input{Scanner: sc}
}
func getInt64() int64 {
	globalInput.Scan()
	x, _ := strconv.ParseInt(globalInput.Text(), 10, 64)
	return x
}
func getInt() int {
	globalInput.Scan()
	x, _ := strconv.Atoi(globalInput.Text())
	return x
}
func getIntOk() (int, bool) {
	ok := globalInput.Scan()
	x, _ := strconv.Atoi(globalInput.Text())
	return x, ok
}
func getNint(n int) []int {
	v := make([]int, n)
	for i := 0; i < n; i++ {
		v[i] = getInt()
	}
	return v
}
func getVint(v []int) bool {
	var ok bool
	for i := 0; i < len(v); i++ {
		v[i], ok = getIntOk()
	}
	return ok
}
func getWord() string {
	globalInput.Scan()
	return globalInput.Text()
}
func getWordOk() (string, bool) {
	ok := globalInput.Scan()
	return globalInput.Text(), ok
}

